kowa na najwy\u017cszej turni Trzech Koron. Wej\u015bcie prowadzi metalowymi schodami i galeriami z por\u0119czami. Lokalizacja znacznika pochodzi z karty PTTK.","tips":"Sezonowe op\u0142aty, zasady i ograniczenia sprawd\u017a na stronie parku: https://piepn.gov.pl/trzy-korony-i-sokolica. Karta nie potwierdza bie\u017c\u0105cego otwarcia ani braku kolejki."},"en":{"name":"Okr\u0105glica \u2014 Trzy Korony viewing gallery","description":"Viewing gallery on the highest tower of Trzy Korony, reached by metal stairs and galleries with handrails. The marker uses the PTTK location.","tips":"Check seasonal fees, rules and restrictions on the park website: https://piepn.gov.pl/trzy-korony-i-sokolica. This card does not confirm current opening or the absence of queues."},"ua":{"name":"Okr\u0105glica \u2014 \u043e\u0433\u043b\u044f\u0434\u043e\u0432\u0430 \u0433\u0430\u043b\u0435\u0440\u0435\u044f Trzy Korony","description":"\u041e\u0433\u043b\u044f\u0434\u043e\u0432\u0430 \u0433\u0430\u043b\u0435\u0440\u0435\u044f \u043d\u0430 \u043d\u0430\u0439\u0432\u0438\u0449\u0456\u0439 \u0441\u043a\u0435\u043b\u044c\u043d\u0456\u0439 \u0432\u0435\u0436\u0456 Trzy Korony. \u0414\u043e\u0441\u0442\u0443\u043f \u043c\u0435\u0442\u0430\u043b\u0435\u0432\u0438\u043c\u0438 \u0441\u0445\u043e\u0434\u0430\u043c\u0438 \u0442\u0430 \u0433\u0430\u043b\u0435\u0440\u0435\u044f\u043c\u0438 \u0437 \u043f\u043e\u0440\u0443\u0447\u043d\u044f\u043c\u0438. \u041f\u043e\u0437\u043d\u0430\u0447\u043a\u0430 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u0454 \u0440\u043e\u0437\u0442\u0430\u0448\u0443\u0432\u0430\u043d\u043d\u044e \u0437 \u043a\u0430\u0440\u0442\u043a\u0438 PTTK.","tips":"\u0421\u0435\u0437\u043e\u043d\u043d\u0456 \u0437\u0431\u043e\u0440\u0438, \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0439 \u043e\u0431\u043c\u0435\u0436\u0435\u043d\u043d\u044f \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0439\u0442\u0435 \u043d\u0430 \u0441\u0430\u0439\u0442\u0456 \u043f\u0430\u0440\u043a\u0443: https://piepn.gov.pl/trzy-korony-i-sokolica. \u041a\u0430\u0440\u0442\u043a\u0430 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u043f\u043e\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0442\u044f \u0447\u0438 \u0432\u0456\u0434\u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0456 \u0447\u0435\u0440\u0433\u0438."},"zh":{"name":"Okr\u0105glica\u2014\u2014Trzy Korony\u89c2\u666f\u5eca\u9053","description":"\u4f4d\u4e8eTrzy Korony\u6700\u9ad8\u5ca9\u5cf0\u7684\u89c2\u666f\u5eca\u9053\uff0c\u9700\u7ecf\u91d1\u5c5e\u697c\u68af\u53ca\u5e26\u6276\u624b\u7684\u5eca\u9053\u62b5\u8fbe\u3002\u6807\u8bb0\u91c7\u7528PTTK\u53d1\u5e03\u7684\u4f4d\u7f6e\u3002","tips":"\u8bf7\u5728\u516c\u56ed\u7f51\u7ad9\u6838\u5b9e\u5b63\u8282\u6027\u8d39\u7528\u3001\u89c4\u5b9a\u53ca\u9650\u5236\uff1ahttps://piepn.gov.pl/trzy-korony-i-sokolica\u3002\u672c\u5361\u7247\u4e0d\u4fdd\u8bc1\u5f53\u524d\u5f00\u653e\u6216\u65e0\u9700\u6392\u961f\u3002"}}}},{"kind":"poi","body":{"peak_slug":"zamkowa-gora","trail_id":null,"type_slug":"attraction","latitude":50.272711,"longitude":17.45885,"active":true,"source_url":"https://go.zopk.pl/korona/","last_verified_at":"2026-11-28T00:00:00Z","website_url":null,"google_maps_url":null,"i18n":{"pl":{"name":"Zamkowa G\u00f3ra \u2014 punkt Korony Parku Krajobrazowego G\u00f3ry Opawskie","description":"Punkt programu turystycznego Zespo\u0142u Opolskich Park\u00f3w Krajobrazowych na Zamkowej G\u00f3rze. Po\u0142o\u017cenie wed\u0142ug oficjalnego pliku lokalizacji odznaki z\u0142otej.","tips":"Warunki zdobywania odznaki i dokumentowania wej\u015bcia sprawd\u017a u organizatora: https://go.zopk.pl/korona/."},"en":{"name":"Zamkowa G\u00f3ra \u2014 Opawskie Landscape Park Crown point","description":"A point in the tourist programme run by the Opole Landscape Parks authority on Zamkowa G\u00f3ra. Location follows its official gold-badge waypoint file.","tips":"Check badge requirements and ascent documentation with the organiser: https://go.zopk.pl/korona/."},"ua":{"name":"Zamkowa G\u00f3ra \u2014 \u0442\u043e\u0447\u043a\u0430 \u041a\u043e\u0440\u043e\u043d\u0438 \u043b\u0430\u043d\u0434\u0448\u0430\u0444\u0442\u043d\u043e\u0433\u043e \u043f\u0430\u0440\u043a\u0443 G\u00f3ry Opawskie","description":"\u0422\u043e\u0447\u043a\u0430 \u0442\u0443\u0440\u0438\u0441\u0442\u0438\u0447\u043d\u043e\u0457 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u0438 \u0423\u043f\u0440\u0430\u0432\u043b\u0456\u043d\u043d\u044f \u043b\u0430\u043d\u0434\u0448\u0430\u0444\u0442\u043d\u0438\u0445 \u043f\u0430\u0440\u043a\u0456\u0432 \u041e\u043f\u043e\u043b\u044c\u0441\u044c\u043a\u043e\u0433\u043e \u0432\u043e\u0454\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043d\u0430 Zamkowa G\u00f3ra. \u0420\u043e\u0437\u0442\u0430\u0448\u0443\u0432\u0430\u043d\u043d\u044f \u0437 \u043e\u0444\u0456\u0446\u0456\u0439\u043d\u043e\u0433\u043e \u0444\u0430\u0439\u043b\u0443 \u0442\u043e\u0447\u043e\u043a \u0437\u043e\u043b\u043e\u0442\u043e\u0457 \u0432\u0456\u0434\u0437\u043d\u0430\u043a\u0438.","tips":"\u0412\u0438\u043c\u043e\u0433\u0438 \u0434\u043e \u0432\u0456\u0434\u0437\u043d\u0430\u043a\u0438 \u0439 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u0441\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u0443\u0442\u043e\u0447\u043d\u044e\u0439\u0442\u0435 \u0432 \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0442\u043e\u0440\u0430: https://go.zopk.pl/korona/."},"zh":{"name":"Zamkowa G\u00f3ra\u2014\u2014G\u00f3ry Opawskie\u666f\u89c2\u516c\u56ed\u5c71\u5cf0\u5fbd\u7ae0\u70b9","description":"\u4f4d\u4e8eZamkowa G\u00f3ra\u7684\u65c5\u6e38\u5fbd\u7ae0\u9879\u76ee\u70b9\uff0c\u7531\u5965\u6ce2\u83b1\u666f\u89c2\u516c\u56ed\u7ba1\u7406\u673a\u6784\u8bbe\u7acb\u3002\u4f4d\u7f6e\u53d6\u81ea\u5b98\u65b9\u91d1\u8272\u5fbd\u7ae0\u822a\u70b9\u6587\u4ef6\u3002","tips":"\u8bf7\u5411\u4e3b\u529e\u65b9\u6838\u5b9e\u5fbd\u7ae0\u8981\u6c42\u53ca\u767b\u9876\u8bb0\u5f55\u65b9\u5f0f\uff1ahttps://go.zopk.pl/korona/\u3002"}}}},{"kind":"poi","body":{"peak_slug":"srebrna-kopa","trail_id":null,"type_slug":"shelter","latitude":50.260819,"longitude":17.432179,"active":true,"source_url":"https://slaskie-opolskie.szlaki.pttk.pl/794-slaskie-opolskie-schronisko-pod-kopa-biskupia","last_verified_at":"2026-11-28T00:00:00Z","website_url":null,"google_maps_url":null,"i18n":{"pl":{"name":"Schronisko PTTK Pod Biskupi\u0105 Kop\u0105","description":"Schronisko pod Biskupi\u0105 Kop\u0105, w pobli\u017cu masywu Srebrnej Kopy. Oddzielny punkt do planowania dalszej w\u0119dr\u00f3wki, poza ko\u0144cem opisanej czerwonej trasy. Lokalizacja wed\u0142ug PTTK.","tips":"Doj\u015bcie do schroniska nie jest cz\u0119\u015bci\u0105 tego GPX. Dost\u0119pno\u015b\u0107 us\u0142ug i nocleg\u00f3w sprawd\u017a bezpo\u015brednio u gospodarza."},"en":{"name":"PTTK Pod Biskupi\u0105 Kop\u0105 hut","description":"Mountain hut below Biskupia Kopa, near the Srebrna Kopa massif. A separate point for planning an onward walk, beyond the end of the described red-trail route. Location follows PTTK.","tips":"Access to the hut is not included in this GPX. Check services and accommodation directly with the operator."},"ua":{"name":"\u041f\u0440\u0438\u0442\u0443\u043b\u043e\u043a PTTK Pod Biskupi\u0105 Kop\u0105","description":"\u0413\u0456\u0440\u0441\u044c\u043a\u0438\u0439 \u043f\u0440\u0438\u0442\u0443\u043b\u043e\u043a \u043f\u0456\u0434 Biskupia Kopa, \u043f\u043e\u0431\u043b\u0438\u0437\u0443 \u043c\u0430\u0441\u0438\u0432\u0443 Srebrna Kopa. \u041e\u043a\u0440\u0435\u043c\u0430 \u0442\u043e\u0447\u043a\u0430 \u0434\u043b\u044f \u043f\u043b\u0430\u043d\u0443\u0432\u0430\u043d\u043d\u044f \u043f\u043e\u0434\u0430\u043b\u044c\u0448\u043e\u0457 \u043c\u0430\u043d\u0434\u0440\u0456\u0432\u043a\u0438, \u0437\u0430 \u043a\u0456\u043d\u0446\u0435\u043c \u043e\u043f\u0438\u0441\u0430\u043d\u043e\u0433\u043e \u0447\u0435\u0440\u0432\u043e\u043d\u043e\u0433\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443. \u0420\u043e\u0437\u0442\u0430\u0448\u0443\u0432\u0430\u043d\u043d\u044f \u0437\u0430 PTTK.","tips":"\u041f\u0456\u0434\u0445\u0456\u0434 \u0434\u043e \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u0443 \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442\u044c \u0434\u043e \u0446\u044c\u043e\u0433\u043e GPX. \u041f\u043e\u0441\u043b\u0443\u0433\u0438 \u0442\u0430 \u043d\u0430\u044f\u0432\u043d\u0456\u0441\u0442\u044c \u043d\u043e\u0447\u0456\u0432\u043b\u0456 \u0443\u0442\u043e\u0447\u043d\u044e\u0439\u0442\u0435 \u0431\u0435\u0437\u043f\u043e\u0441\u0435\u0440\u0435\u0434\u043d\u044c\u043e \u0432 \u0430\u0434\u043c\u0456\u043d\u0456\u0441\u0442\u0440\u0430\u0446\u0456\u0457."},"zh":{"name":"PTTK Pod Biskupi\u0105 Kop\u0105\u5c71\u5c4b","description":"\u4f4d\u4e8eBiskupia Kopa\u4e0b\u65b9\u3001Srebrna Kopa\u5c71\u4f53\u9644\u8fd1\u7684\u5c71\u5c4b\uff0c\u53ef\u7528\u4e8e\u89c4\u5212\u540e\u7eed\u884c\u7a0b\uff0c\u4f4d\u4e8e\u6240\u8ff0\u7ea2\u8272\u6b65\u9053\u7ec8\u70b9\u4e4b\u5916\u3002\u4f4d\u7f6e\u4f9d\u636ePTTK\u3002","tips":"\u672cGPX\u4e0d\u5305\u542b\u524d\u5f80\u5c71\u5c4b\u7684\u8def\u6bb5\u3002\u8bf7\u76f4\u63a5\u5411\u7ecf\u8425\u8005\u6838\u5b9e\u670d\u52a1\u53ca\u4f4f\u5bbf\u3002"}}}}],"ranges":[{"id":8,"slug":"rudawy-janowickie"},{"id":15,"slug":"gory-opawskie"},{"id":26,"slug":"pieniny"}]}$manifest$::jsonb m),
expected as (select p, (select r->'body' from jsonb_array_elements(m->'records') r where r->>'kind'='trail' and r->'body'->>'peak_slug'=p->>'slug') tb,
 (select r->'body' from jsonb_array_elements(m->'records') r where r->>'kind'='poi' and r->'body'->>'peak_slug'=p->>'slug') pb
 from manifest,jsonb_array_elements(m->'peaks') p)
select e.p->>'slug' peak_slug, mr.slug range_slug,
 (select count(*) from public.trails where peak_id=p.id and active) trails,
 (select count(*) from public.pois where peak_id=p.id and active) pois,
 case when t.route_geometry is not null then 1 else 0 end mapped_trails,
 (select array_agg(lang order by lang collate "C") from public.trails_i18n where trail_id=t.id) trail_languages,
 (select array_agg(lang order by lang collate "C") from public.pois_i18n where poi_id=poi.id) poi_languages,
 coalesce((select jsonb_object_agg(k,to_jsonb(p)->k) from jsonb_object_keys(e.p) k)=e.p
 and mr.slug=(select r->>'slug' from manifest,jsonb_array_elements(m->'ranges') r where (r->>'id')::bigint=p.range_id)
 and not exists(select from unnest(array['peak_id','slug','start_point_name','end_point_name','distance_km','elevation_gain_m','time_min','difficulty','route_type','active','source_url','last_verified_at','map_url','gpx_url','distance_source_url','distance_verified_at','elevation_gain_source_url','elevation_gain_verified_at','time_source_url','time_verified_at','route_geometry','geometry_source_url','geometry_verified_at']) k where to_jsonb(t)->k is distinct from to_jsonb(jsonb_populate_record(null::public.trails,e.tb||jsonb_build_object('peak_id',p.id)))->k)
 and not exists(select from unnest(array['peak_id','trail_id','type_id','latitude','longitude','active','source_url','last_verified_at','website_url','google_maps_url']) k where to_jsonb(poi)->k is distinct from to_jsonb(jsonb_populate_record(null::public.pois,e.pb||jsonb_build_object('peak_id',p.id,'type_id',ty.id)))->k)
 and (select jsonb_object_agg(lang,jsonb_build_object('name',name,'description',description,'notes',notes)) from public.trails_i18n where trail_id=t.id)=e.tb->'i18n'
 and (select jsonb_object_agg(lang,jsonb_build_object('name',name,'description',description,'tips',tips)) from public.pois_i18n where poi_id=poi.id)=e.pb->'i18n',false) review_matches,
 exists(select from peakguide_private.catalogue_batch_receipts where batch_key='nonkgp-08' and snapshot->>'manifest_sha256'='51059849965926fc911a417b8c181ddefbf4710e8705e73cecf846f1872cffef' and snapshot->>'version'='1') package_applied
from expected e left join public.peaks p on p.id=(e.p->>'id')::bigint and p.slug=e.p->>'slug'
left join public.mountain_ranges mr on mr.id=p.range_id
left join public.trails t on t.peak_id=p.id and t.slug=e.tb->>'slug'
left join public.poi_types ty on ty.slug=e.pb->>'type_slug'
left join public.pois poi on poi.peak_id=p.id and poi.source_url=e.pb->>'source_url' and poi.type_id=ty.id
order by e.p->>'slug';
